# Pre-push check of the Rust workspace with rust-analyzer's own diagnostics (no compilation).
#
# rust-analyzer analyses the sources without compiling anything. Build scripts and the proc-macro
# server stay disabled (both --disable flags are always passed), so this is safe on machines where
# endpoint protection blocks freshly compiled executables. It reports syntax errors, type
# mismatches, wrong argument counts, unknown methods, unresolved names and imports. It cannot see
# code generated by derive macros and skips #[cfg(test)] code, so CI stays the authority for
# compilation, clippy and tests.
#
# Usage (PowerShell, from anywhere):   rust/tools/ra_check.ps1 [-All]
#   -All   also print the WeakWarning lines (inactive code, "proc-macro not yet built", ...)
# Exit code: rust-analyzer's (non-zero when it found an error).
param([switch]$All)

$ErrorActionPreference = 'Stop'
$workspace = Split-Path -Parent $PSScriptRoot   # the rust/ directory

$ra = $null
$candidates = @()
if ($env:RUST_ANALYZER) { $candidates += $env:RUST_ANALYZER }
$extDir = Join-Path $env:USERPROFILE '.vscode\extensions'
if (Test-Path $extDir) {
    $candidates += Get-ChildItem $extDir -Directory -Filter 'rust-lang.rust-analyzer-*' |
        Sort-Object Name -Descending |
        ForEach-Object { Join-Path $_.FullName 'server\rust-analyzer.exe' }
}
foreach ($c in $candidates) { if (Test-Path $c) { $ra = $c; break } }
if (-not $ra) {
    Write-Error 'rust-analyzer not found: install the rust-lang.rust-analyzer VS Code extension or set RUST_ANALYZER'
    exit 2
}

Write-Host "rust-analyzer: $ra"
Write-Host "workspace:     $workspace"
# rust-analyzer writes its summary to stderr; collect both streams as text
$ErrorActionPreference = 'Continue'
$lines = & $ra diagnostics --disable-build-scripts --disable-proc-macros $workspace 2>&1 | ForEach-Object { "$_" }
$code = $LASTEXITCODE
# With proc macros disabled, rust-analyzer does not see the code generated by #[derive(...)]
# (serde Serialize/Deserialize, thiserror Display). Errors that only say such a trait (or a method
# it provides, like to_string on an error type) is missing are therefore expected and are counted
# separately; -All shows them.
$deriveNoise = 'Serialize|Deserialize|Display|no method `to_string`|backtrace|^\s+\d+: |^\s+at /rustc|RemoteException|diagnostic error detected|required by the bound|^\s*$'
$shown = 0; $errors = 0; $noise = 0
foreach ($l in $lines) {
    if ($l -match 'WeakWarning') { if ($All) { Write-Host $l }; continue }
    if ($l -match $deriveNoise -and $l -notmatch 'Error Syntax') {
        $noise++
        if ($All) { Write-Host $l }
        continue
    }
    Write-Host $l; $shown++
    if ($l -match ': Error ') { $errors++ }
}
Write-Host "rust-analyzer exit code $code; $errors error(s) shown, $noise derive-macro or summary line(s) hidden"
if ($errors -gt 0) { exit 1 }
exit 0
